verb :can_be_attached_by(who) rxd {
  /* Mounting the acts feature is a seed/owner act on the consumer side
     ($case:initialize); the feature itself is freely attachable. */
  return true;
}

verb :act(type, payload) r {
  /* Internal emission primitive (ACT3). A space composes on its own log;
     a catalog-owned anchored actor composes on its containing space's log.
     Direct routes carry seq == -1. In both forms only the composer's own
     verbs may call this primitive (caller == this). Any fold failure aborts
     the whole turn: fail-closed. */
  if (seq < 1) { raise { code: "E_INVARG", message: "acts require a sequenced turn" }; }
  let bound_log = null;
  if (isa(this, $space)) { bound_log = this; }
  else if (isa(this, $actor)) { bound_log = location(this); }
  if (bound_log == null || !isa(bound_log, $space) || space != bound_log) {
    /* This is an incompatible semantic-space request, not malformed Act data.
       Name it as such even when failure atomicity removes the provisional
       writes before Net selects a commit scope. */
    raise { code: "E_SCOPE_SPLIT", message: "act composer is not bound to this sequenced log", value: { composer: this, log_space: space } };
  }
  if (caller != this) { raise { code: "E_PERM", message: "acts are emitted by composer verbs only" }; }
  let shape = event_schema(this, type);
  if (shape == null) { raise { code: "E_INVARG", message: "unknown act type", value: type }; }
  this:_validate_payload(type, shape, payload);
  /* source is generic carrier metadata naming the composer, not a semantic
     Act field. It lets rebuild distinguish several composers on one log. */
  let act = { "type": type, "version": 1, "payload": payload, "source": this };
  /* Live emission and rebuild inject the same recorded envelope identity.
     None of seq, actor, or source belongs in the validated payload. */
  let fold_input = { "type": type, "version": 1, "payload": payload, "seq": seq, "actor": actor, "source": this };
  let projections = [];
  try { projections = this.projections; } except e in (E_PROPNF) { }
  for p in projections {
    if (!valid(p) || !isa(p, $projection) || p.source_space != this || p.log_space != bound_log) {
      raise { code: "E_INVARG", message: "projection is not bound to the emitting composer and log", value: p };
    }
    if (type in p.consumes) { p:fold(fold_input); }
  }
  observe(act);
  return act;
}

verb :_validate_payload(type, shape, payload) r {
  /* Closed flat shape vocabulary (S2.2): obj, str, bool, int, float,
     num, list, map, null — with unions as "a|b" alternatives (earned by
     the outliner migration, whose declared shapes use "obj|null").
     Every declared key is required; undeclared keys refuse. Exact
     typing: "str" refuses live object refs (refs are strings at the VM
     level - an obj must not pass as a code/label); "obj" requires a
     live ref. */
  if (caller != this) { raise { code: "E_PERM", message: "payload validation is internal" }; }
  if (typeof(payload) != "map") { raise { code: "E_INVARG", message: "act payload must be a map", value: type }; }
  for pk, pv in payload {
    if (!(pk in shape)) { raise { code: "E_INVARG", message: "undeclared act payload key", value: pk }; }
  }
  for k, spec in shape {
    if (!(k in payload)) { raise { code: "E_INVARG", message: "missing act payload key", value: k }; }
    let val = payload[k];
    let ok = false;
    for t in str_split(spec, "|") {
      if (ok) { continue; }
      if (t == "obj") { ok = typeof(val) == "string" && valid(val); }
      else if (t == "str") { ok = typeof(val) == "string" && !valid(val); }
      else if (t == "bool") { ok = typeof(val) == "boolean"; }
      else if (t == "int") { ok = typeof(val) == "number" && floor(val) == val; }
      else if (t == "float" || t == "num") { ok = typeof(val) == "number"; }
      else if (t == "list") { ok = typeof(val) == "list"; }
      else if (t == "map") { ok = typeof(val) == "map"; }
      else if (t == "null") { ok = val == null; }
      else { raise { code: "E_INVARG", message: "unsupported shape tag", value: t }; }
    }
    if (!ok) { raise { code: "E_INVARG", message: "act payload type mismatch", value: k }; }
  }
  return true;
}

verb :_rebuild_projection(projection, log_space, page_budget) r {
  /* Composer-mediated replay keeps :fold single-authority. An anchored actor
     composes while its separately bound containing space owns the log. The
     projection may request replay but cannot supply fold input. */
  if (!valid(projection) || !isa(projection, $projection) || projection.source_space != this || projection.log_space != log_space || caller != projection) {
    raise { code: "E_PERM", message: "projection rebuild is authority-internal", value: projection };
  }
  if (!valid(log_space) || !isa(log_space, $space)) { raise { code: "E_INVARG", message: "projection rebuild requires its bound log space", value: log_space }; }
  if (actor != projection.owner && !has_flag(actor, "wizard")) { raise { code: "E_PERM", message: "rebuild is owner-only" }; }
  let budget = 100;
  if (typeof(page_budget) == "number" && page_budget >= 1 && page_budget <= 100) { budget = toint(page_budget); }
  let from = projection.at_seq;
  if (projection.rebuild_scan_seq > from) { from = projection.rebuild_scan_seq; }
  from = from + 1;
  let entries = log_space:replay(from, budget);
  let scanned = from - 1;
  for e in entries {
    scanned = e["seq"];
    if (!e["applied_ok"]) { continue; }
    for o in e["observations"] {
      if (typeof(o) == "map" && ("type" in o) && ("payload" in o) && ("version" in o) && o["source"] == this && (o["type"] in projection.consumes)) {
        /* Reconstruct exactly the live fold envelope. Source selects this
           composer on a shared log; actor comes from its recorded message. */
        let input = { "type": o["type"], "version": o["version"], "payload": o["payload"], "seq": e["seq"], "actor": e["message"]["actor"], "source": this };
        projection:fold(input);
      }
    }
  }
  projection.rebuild_scan_seq = scanned;
  return { "at_seq": projection.at_seq, "scanned_seq": scanned, "done": length(entries) < budget };
}

verb :fold(act) r {
  if (caller != this.source_space) { raise { code: "E_PERM", message: "projection fold is authority-internal" }; }
  /* Subclass responsibility (ACT4): deterministic given (projection state,
     act), sole writer of that state, no scan beyond the payload and declared
     fixed caps, no clock, and no foreign reads. The act input carries recorded
     envelope seq, actor, and composer source alongside the semantic body. The
     base refuses so an unimplemented projection fails loudly. */
  raise { code: "E_VERBNF", message: "projection must implement :fold" };
}

verb :view(opts) rxd {
  /* The one authoritative bounded read (S2.3). Pages rows in key order
     with a continuation cursor: pass opts["after"] = the previous
     page's "cursor" to fetch the next page (a stale/unknown cursor
     yields an empty page). at_seq is the seq of the LAST CONSUMED act -
     a conservative completeness watermark, not the room's head seq.
     Each row renders through :view_row so subclasses join
     object-authoritative facts at view time without mirroring them. */
  if (typeof(opts) != "map") { opts = {}; }
  let limit = 50;
  if ("limit" in opts) { limit = toint(opts["limit"]); }
  if (limit < 1 || limit > 200) { limit = 50; }
  let after = "";
  if ("after" in opts) { after = to_string(opts["after"]); }
  let skipping = after != "";
  let page = [];
  let cursor = null;
  let has_more = false;
  for k in keys(this.rows) {
    if (skipping) { if (k == after) { skipping = false; } continue; }
    if (length(page) >= limit) { has_more = true; break; }
    page = page + [this:view_row(k, this.rows[k])];
    cursor = k;
  }
  return { "page": page, "at_seq": this.at_seq, "cursor": cursor, "has_more": has_more };
}

verb :view_row(key, row) r {
  if (caller != this) { raise { code: "E_PERM", message: "projection row rendering is internal" }; }
  /* Default rendering: the stored row itself. */
  return row;
}

verb :rebuild_from(log_space, page_budget) rxd {
  /* Operator rebuild (ACT4): the bound composer mediates replay from the
     separately bound log, preserving one fold caller for space and anchored
     actor composers alike. */
  if (log_space != this.log_space) { raise { code: "E_INVARG", message: "rebuild source does not match projection log authority", value: log_space }; }
  if (actor != this.owner && !has_flag(actor, "wizard")) { raise { code: "E_PERM", message: "rebuild is owner-only" }; }
  return this.source_space:_rebuild_projection(this, log_space, page_budget);
}
